#include <stdio.h>

void print_array(const int a[], int n) {
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

int selection_sort(int a[], int n) {
    int swaps = 0;
    for (int i = 0; i < n - 1; i++) {
        int min = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[min])
                min = j;
        }
        if (min != i) {
            int temp = a[i];
            a[i] = a[min];
            a[min] = temp;
            swaps++;
        }
        printf("Pass %d: ", i + 1);
        print_array(a, n);
    }
    return swaps;
}

int main(void) {
    int heights[] = {5, 2, 9, 1, 6, 3};
    int n = sizeof(heights) / sizeof(heights[0]);

    int swaps = selection_sort(heights, n);
    printf("Swaps: %d\n", swaps);
    return 0;
}

